diff --git a/src/orchestration/chatOrchestrator.test.ts b/src/orchestration/chatOrchestrator.test.ts
index 2839ef8..28bf9d7 100644
--- a/src/orchestration/chatOrchestrator.test.ts
+++ b/src/orchestration/chatOrchestrator.test.ts
@@ -612,4 +612,51 @@ describe('ChatOrchestrator tool loop', () => {

     expect(seen).toEqual({inputTokens: 30, outputTokens: 12, totalTokens: 42});
   });
+
+  it('sums usage only from rounds that report it, leaving an unreported turn undefined', async () => {
+    let seenWithGaps: TotalUsage | undefined;
+    let seenWithoutUsage: TotalUsage | undefined;
+    const withGaps = createChatOrchestrator(
+      scriptedProvider([
+        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 2, outputTokens: 1, totalTokens: 3}}],
+        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use'}],
+        [
+          {type: 'text', text: 'done'},
+          {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 7, outputTokens: 4, totalTokens: 11}},
+        ],
+      ]),
+      promptBuilder,
+      registryReturning({result: 'r'}),
+      {
+        hooks: {
+          afterModelResponse: async (_session, _text, totalUsage) => {
+            seenWithGaps = totalUsage;
+          },
+        },
+      }
+    );
+    const withoutUsage = createChatOrchestrator(
+      scriptedProvider([
+        [
+          {type: 'text', text: 'done'},
+          {type: 'stop', stopReason: 'end_turn'},
+        ],
+      ]),
+      promptBuilder,
+      undefined,
+      {
+        hooks: {
+          afterModelResponse: async (_session, _text, totalUsage) => {
+            seenWithoutUsage = totalUsage;
+          },
+        },
+      }
+    );
+
+    await withGaps.processMessage(createSession('ask'));
+    await withoutUsage.processMessage(createSession('ask'));
+
+    expect(seenWithGaps).toEqual({inputTokens: 9, outputTokens: 5, totalTokens: 14});
+    expect(seenWithoutUsage).toBeUndefined();
+  });
 });

